ZWN0W10geyByb290IH0pOwogICAgICAgICAgICBzaG9ydGN1dFR5cGUuSW52b2tlTWVtYmVyKCJJY29uTG9jYXRpb24iLCBCaW5kaW5nRmxhZ3MuU2V0UHJv
cGVydHksIG51bGwsIHNob3J0Y3V0LCBuZXcgb2JqZWN0W10geyBleGVQYXRoICsgIiwwIiB9KTsKICAgICAgICAgICAgc2hvcnRjdXRUeXBlLkludm9rZU1l
bWJlcigiRGVzY3JpcHRpb24iLCBCaW5kaW5nRmxhZ3MuU2V0UHJvcGVydHksIG51bGwsIHNob3J0Y3V0LAogICAgICAgICAgICAgICAgbmV3IG9iamVjdFtd
IHsgIkFnZSBvZiB0aGUgUmluZyAtIDggUGxheWVyIFdhciBvZiB0aGUgUmluZyIgfSk7CiAgICAgICAgICAgIHNob3J0Y3V0VHlwZS5JbnZva2VNZW1iZXIo
IlNhdmUiLCBCaW5kaW5nRmxhZ3MuSW52b2tlTWV0aG9kLCBudWxsLCBzaG9ydGN1dCwgbnVsbCk7CiAgICAgICAgICAgIExvZ1VwZGF0ZSgiRGVza3RvcCBz
aG9ydGN1dCByZWJ1aWx0IGZvciBsYXVuY2hlciAiICsgTGF1bmNoZXJWZXJzaW9uICsgIjogIiArIHNob3J0Y3V0UGF0aCk7CiAgICAgICAgfQogICAgICAg
IGNhdGNoIChFeGNlcHRpb24gZXgpCiAgICAgICAgewogICAgICAgICAgICBMb2dVcGRhdGUoIkRlc2t0b3Agc2hvcnRjdXQgcmVidWlsZCBmYWlsZWQ6ICIg
KyBleC5NZXNzYWdlKTsKICAgICAgICB9CiAgICB9Cn0KCi8vIFB1YmxpYyBicmlkZ2UgdXNlZCBieSB0aGUgZW1iZWRkZWQgV1BGIFBvd2VyU2hlbGwgR1VJ
LiBJdCBkZWxpYmVyYXRlbHkgZXhwb3NlcwovLyBvbmx5IG9uZSBuYXJyb3cgb3BlcmF0aW9uOiBhc2sgdGhlIGFscmVhZHktdGVzdGVkIG5hdGl2ZSB1cGRh
dGVyIHRvIGNoZWNrIG5vdy4KcHVibGljIHN0YXRpYyBjbGFzcyBBb3RSOFBVcGRhdGVCcmlkZ2UKewogICAgcHVibGljIHN0YXRpYyBzdHJpbmcgQ2hlY2tO
b3coKQogICAgewogICAgICAgIHJldHVybiBQcm9ncmFtLk1hbnVhbFVwZGF0ZUNoZWNrKCk7CiAgICB9Cn0KCg==
'@))

    $safeUrl = $UpdateManifestUrl.Replace("\", "\\").Replace('"','\"')
    $safeVersion = $LauncherVersion.Replace("\", "\\").Replace('"','\"')
    $source = $template.Replace("__UPDATE_URL__", $safeUrl).Replace("__LAUNCHER_VERSION__", $safeVersion).Replace("__FILE_VERSION__", $fileVersion)

    [IO.File]::WriteAllText($csPath, $source, (New-Object Text.UTF8Encoding($false)))

    $manifest = @'
<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<assembly xmlns="urn:schemas-microsoft-com:asm.v1" manifestVersion="1.0">
  <assemblyIdentity version="1.0.0.0" name="eliaauditore.AotR8PWotRMod.SingleExe"/>
  <trustInfo xmlns="urn:schemas-microsoft-com:asm.v3">
    <security>
      <requestedPrivileges>
        <requestedExecutionLevel level="requireAdministrator" uiAccess="false"/>
      </requestedPrivileges>
    </security>
  </trustInfo>
  <application xmlns="urn:schemas-microsoft-com:asm.v3">
    <windowsSettings>
      <dpiAware xmlns="http://schemas.microsoft.com/SMI/2005/WindowsSettings">true</dpiAware>
    </windowsSettings>
  </application>
</assembly>
'@
    [IO.File]::WriteAllText($manifestPath,$manifest,(New-Object Text.UTF8Encoding($false)))

    Write-Host "Compiling embedded Single-EXE launcher..." -ForegroundColor Cyan

    $out = & $csc `
        "/nologo" `
        "/target:winexe" `
        "/optimize+" `
        "/platform:anycpu" `
        "/reference:System.Windows.Forms.dll" `
        "/reference:System.Web.Extensions.dll" `
        "/reference:$automation" `
        "/win32icon:$Icon" `
        "/win32manifest:$manifestPath" `
        "/out:$newExe" `
        "$csPath" 2>&1

    if ($LASTEXITCODE -ne 0 -or -not (Test-Path -LiteralPath $newExe -PathType Leaf)) {
        $out | ForEach-Object { Write-Host $_ -ForegroundColor Red }
        throw "Single-EXE compilation failed."
    }

    $bytes = [IO.File]::ReadAllBytes($newExe)
    if ($bytes.Length -lt 4096 -or $bytes[0] -ne 0x4D -or $bytes[1] -ne 0x5A) {
        throw "Compiled file is not a valid Windows PE executable."
    }

    $builtHash = Get-Sha256 $newExe

    if ($EmitGitHubBundle) {
        $bundleRoot = Join-Path $PackageRoot "_GITHUB_UPDATE"
        $bundleUpdate = $bundleRoot
        if (Test-Path -LiteralPath $bundleRoot) {
            Remove-Item -LiteralPath $bundleRoot -Recurse -Force
        }
        New-Item -ItemType Directory -Force -Path $bundleUpdate | Out-Null
        Copy-Item -LiteralPath $newExe -Destination (Join-Path $bundleUpdate "AotR 8P WotR Mod.exe") -Force

        # Keep schema=1 so already released launchers can still self-update.
        # Newer launchers simply consume the additional repair/payload metadata.
        $repoRaw = "https://raw.githubusercontent.com/eliaauditore/AotR-8P-WotR/main"
        $manifestObject = [ordered]@{
            schema = 1
            launcher_version = $LauncherVersion
            launcher_url = $UpdateBinaryUrl
            launcher_sha256 = $builtHash
            mandatory = $false

            repair_manifest_url = "$repoRaw/repair-manifest.json"
            ui_url = "$repoRaw/payload_ui.big"
            ui_sha256 = $ExpectedUi
            paper_url = "$repoRaw/payload_paper.inc"
            paper_sha256 = $ExpectedPaper
        }
        $manifestJson = $manifestObject | ConvertTo-Json -Depth 6
        [IO.File]::WriteAllText(
            (Join-Path $bundleUpdate "manifest.json"),
            $manifestJson + [Environment]::NewLine,
            (New-Object Text.UTF8Encoding($false))
        )

        # Repair payloads are immutable verified copies. AUTO REPAIR will only install
        # them after their SHA256 matches the hashes above.
        Copy-Item -LiteralPath $Ui -Destination (Join-Path $bundleUpdate "payload_ui.big") -Force
        Copy-Item -LiteralPath $Paper -Destination (Join-Path $bundleUpdate "payload_paper.inc") -Force

        # Remote plans may ONLY select actions from the launcher's built-in allow-list.
        # This file can therefore tune repair recipes without shipping executable code.
        $repairManifest = [ordered]@{
            schema = 1
            generated_for_launcher = $LauncherVersion
            plans = [ordered]@{
                "A8P-INSTALL-001" = [ordered]@{
                    actions = @("reset_install","retry_launch")
                }
                "A8P-PAYLOAD-UI-001" = [ordered]@{
                    actions = @("repair_payloads","reset_runtime","retry_launch")
                }
                "A8P-PAYLOAD-PAPER-001" = [ordered]@{
                    actions = @("repair_payloads","reset_runtime","retry_launch")
                }
                "A8P-LEGACY-001" = [ordered]@{
                    actions = @("stop_old_dev_launchers","stop_legacy_runtime","retry_launch")
                }
                "A8P-PROCESS-001" = [ordered]@{
                    actions = @("stop_legacy_runtime","stop_failed_game","retry_launch")
                }
                "A8P-RUNTIME-001" = [ordered]@{
                    actions = @("stop_legacy_runtime","stop_failed_game","reset_runtime","repair_payloads","retry_launch")
                }
                "A8P-GAMEPROC-001" = [ordered]@{
                    actions = @("stop_legacy_runtime","stop_failed_game","reset_runtime","retry_launch")
                }
                "A8P-PERMISSION-001" = [ordered]@{
                    actions = @("stop_failed_game","retry_launch")
                }
                "A8P-COMPAT-001" = [ordered]@{
                    actions = @("check_launcher_update")
                    protected = $true
                }
                "A8P-ENGINE-001" = [ordered]@{
                    actions = @("stop_legacy_runtime","stop_failed_game","reset_runtime","clear_compat_cache","retry_launch")
                }
            }
        }
        [IO.File]::WriteAllText(
            (Join-Path $bundleUpdate "repair-manifest.json"),
            (($repairManifest | ConvertTo-Json -Depth 8) + [Environment]::NewLine),
            (New-Object Text.UTF8Encoding($false))
        )
    }

    if (-not $BundleOnly) {
        $backupRoot = Join-Path $env:LOCALAPPDATA "AotR 8P WotR Mod\seed_backup"
        New-Item -ItemType Directory -Force -Path $backupRoot | Out-Null
        $backup = Join-Path $backupRoot ("AotR 8P WotR Mod_PRE_" + $LauncherVersion.Replace('.','_') + "_" + (Get-Date -Format "yyyyMMdd_HHmmss") + ".exe")
        Copy-Item -LiteralPath $Launcher -Destination $backup -Force
        Copy-Item -LiteralPath $newExe -Destination $Launcher -Force

        Write-Host ""
        Write-Host "[OK] Single-EXE launcher installed locally." -ForegroundColor Green
        Write-Host ("Launcher : " + $Launcher)
        Write-Host ("Version  : " + $LauncherVersion)
        Write-Host ("SHA256   : " + (Get-Sha256 $Launcher))
        Write-Host ("Backup   : " + $backup)
        Write-Host ("Updater  : " + $UpdateManifestUrl) -ForegroundColor Green
    } else {
        Write-Host ""
        Write-Host "[OK] Update launcher built without replacing the local launcher." -ForegroundColor Green
        Write-Host ("Version  : " + $LauncherVersion)
        Write-Host ("SHA256   : " + $builtHash)
    }

    if ($EmitGitHubBundle) {
        Write-Host ("GitHub   : " + (Join-Path $PackageRoot "_GITHUB_UPDATE")) -ForegroundColor Cyan
        Write-Host "          Upload ALL FIVE files in that folder to the repository ROOT." -ForegroundColor Cyan
        Write-Host "          EXE + manifest.json + repair-manifest.json + payload_ui.big + payload_paper.inc" -ForegroundColor Cyan
    }
    Write-Host ""
    Write-Host "GUI + diagnostics + REPORT ERROR + MESSAGES + engine + FINAL_STABLE_V7 + AUTO REPAIR remain embedded in the EXE." -ForegroundColor Green
    Write-Host "No external launcher/engine PowerShell files are executed by the launcher."
}
finally {
    Remove-Item -LiteralPath $tempRoot -Recurse -Force -ErrorAction SilentlyContinue
}
